func:
// --- 後台：整合台灣 CWA 與 日本 Open-Meteo 資料 ---

// 1. 定義台灣區域
const regionMap = {
    "北部": ["基隆市", "臺北市", "新北市", "桃園市", "新竹市", "新竹縣", "宜蘭縣"],
    "中部": ["苗栗縣", "臺中市", "彰化縣", "南投縣", "雲林縣"],
    "南部": ["嘉義市", "嘉義縣", "臺南市", "高雄市", "屏東縣"],
    "東部": ["花蓮縣", "臺東縣"],
    "離島": ["澎湖縣", "金門縣", "連江縣"]
};

let finalData = {};

// --- 2. 處理台灣資料 (從 msg.taiwan 讀取) ---
if (msg.taiwan && msg.taiwan.records) {
    let twCities = msg.taiwan.records.location;
    twCities.forEach(city => {
        let name = city.locationName;
        let we = city.weatherElement;

        // 找區域
        for (let region in regionMap) {
            if (regionMap[region].includes(name)) {
                if (!finalData[region]) finalData[region] = [];
                // 存入格式
                finalData[region].push({
                    city: name,
                    // 抓第一筆(現在)和第二筆(預測)
                    minT: [we.find(e=>e.elementName=="MinT").time[0], we.find(e=>e.elementName=="MinT").time[1]],
                    maxT: [we.find(e=>e.elementName=="MaxT").time[0], we.find(e=>e.elementName=="MaxT").time[1]],
                    wx:   [we.find(e=>e.elementName=="Wx").time[0],   we.find(e=>e.elementName=="Wx").time[1]]
                });
                break;
            }
        }
    });
}

// --- 3. 處理日本資料 (從 msg.payload 讀取) ---
// 日本 API 回傳的是 WMO 代碼，我們寫個簡單轉換
function wmoCodeToText(code) {
    if(code === 0) return "晴朗";
    if(code <= 3) return "多雲";
    if(code <= 67) return "陰雨";
    if(code <= 77) return "下雪"; // 重點！
    if(code <= 86) return "陣雪";
    return "有雪";
}

if (msg.payload && msg.payload.daily) {
    let jpData = msg.payload;
    let jpDaily = jpData.daily;

    // 建立一個新的「日本地區」
    finalData["日本"] = [];

    // 手動建立札幌資料，模擬成台灣 CWA 的格式結構，這樣前台不用改程式
    // 日本 API 給的是每日最高低溫
    let minT_Now = jpDaily.temperature_2m_min[0];
    let maxT_Now = jpDaily.temperature_2m_max[0];
    let wx_Now   = wmoCodeToText(jpDaily.weathercode[0]);

    let minT_Next = jpDaily.temperature_2m_min[1]; // 明天
    let maxT_Next = jpDaily.temperature_2m_max[1];
    let wx_Next   = wmoCodeToText(jpDaily.weathercode[1]);

    finalData["日本"].push({
        city: "北海道(札幌)",
        minT: [
            { parameter: { parameterName: minT_Now } }, // 模擬結構
            { parameter: { parameterName: minT_Next }, startTime: "明日預報" }
        ],
        maxT: [
            { parameter: { parameterName: maxT_Now } },
            { parameter: { parameterName: maxT_Next } }
        ],
        wx: [
            { parameter: { parameterName: wx_Now } },
            { parameter: { parameterName: wx_Next } }
        ]
    });

    // 您也可以多加一個東京
    // 但為了簡化流程，我們先只加最冷的北海道
}

// 存入倉庫
global.set("weatherData_36H", finalData);
return msg;

// --- 前台：讀取資料、產生多樣化建議、計算12小時預警 ---
let selectedRegion = msg.payload; 
let allData = global.get("weatherData_36H"); 

if (!allData) {
    node.warn("無資料，請按上方的 Inject 按鈕");
    msg.payload = []; 
    return msg;
}

let regionData = allData[selectedRegion];
let outputArray = [];

// --- 1. 超級食補資料庫 (多樣化越多越好) ---
const foodDB = {
    // 寒冷 (<15度) - 溫補暖身
    cold: [
        "薑母鴨", "藥燉排骨", "麻油雞", "羊肉爐", 
        "札幌拉麵", "石狩鍋(鮭魚火鍋)", "溫清酒", "壽喜燒",// 新增日式
        "薑母鴨", "藥燉排骨", "麻油雞", "羊肉爐", "當歸鴨麵線", 
        "十全大補湯", "燒酒雞", "麻油腰子", "桂圓紅棗茶", "黑糖薑茶",
        "胡椒豬肚雞", "蒜頭蛤蜊雞", "韓式人蔘雞", "麻辣鍋"
    ],
    // 微涼 (15-20度) - 平補護氣
    cool: [
        "香菇雞湯", "四神湯", "蒜頭雞", "剝皮辣椒雞", "山藥排骨湯",
        "蛤蜊湯", "味噌魚湯", "羅宋湯", "麻油麵線", "熱豆花",
        "排骨酥湯", "虱目魚粥", "牛肉湯", "茶碗蒸"
    ],
    // 舒適 (20-28度) - 清爽養生
    normal: [
        "銀耳蓮子湯", "無糖豆漿", "番茄牛肉湯", "清炒地瓜葉", "鱸魚湯",
        "蓮藕排骨湯", "青木瓜排骨", "涼拌小黃瓜", "水果優格", "蒸蛋",
        "白木耳湯", "南瓜濃湯", "鮮魚湯", "雞肉沙拉"
    ],
    // 炎熱 (>28度) - 退火消暑
    hot: [
        "綠豆湯", "薏仁水", "冬瓜茶", "苦瓜排骨湯", "西瓜",
        "仙草蜜", "愛玉檸檬", "菊花茶", "椰子水", "涼拌竹筍",
        "絲瓜蛤蜊", "皮蛋豆腐", "冷泡茶", "酸梅湯"
    ]
};

// --- 2. 完整農民曆資料庫 ---
const yiDB = ["祭祀", "出行", "嫁娶", "移徙", "修造", "動土", "安床", "納財", "開市", "會友", "沐浴", "理髮", "栽種", "納畜", "安門"];
const jiDB = ["安葬", "作灶", "入宅", "破土", "伐木", "訴訟", "針灸", "開倉", "遠行", "探病"];

// 取得今天日期種子
let today = new Date();
let daySeed = today.getDate() + (today.getMonth() * 30); // 讓每個月的同一號也不同

if (regionData) {
    regionData.forEach(item => {
        // --- 3. 取得現在與未來數據 ---
        let nowMin = parseInt(item.minT[0].parameter.parameterName);
        let nowMax = parseInt(item.maxT[0].parameter.parameterName);
        let nextMin = parseInt(item.minT[1].parameter.parameterName);
        let nextWx  = item.wx[1].parameter.parameterName;
        let nextTime = item.minT[1].startTime.substring(5, 13); // "MM-DD HH"

        // --- 4. 計算預警 (重點！) ---
        let forecastMsg = `未來 12h 持平，天氣${nextWx}`;
        let alertClass = "normal"; // 預設灰色

        if (nextMin < nowMin - 3) {
            forecastMsg = `📉 注意！氣溫驟降，將降至 ${nextMin}°C`;
            alertClass = "warning";
        } else if (nextMin <= 12) {
            forecastMsg = `❄️ 寒流來襲警報！低溫 ${nextMin}°C`;
            alertClass = "danger";
        } else if (nextMin > nowMin + 3) {
            forecastMsg = `📈 氣溫回升，將升至 ${nextMin}°C`;
            alertClass = "safe";
        }

        // --- 5. 決定食補類別 ---
        let category = "normal";
        let status = "舒適";
        let risk = "safe";
        let icon = "fa-sun-o";

        if (nowMin <= 16) {
            category = "cold"; risk = "danger"; status = "寒冷"; icon = "fa-snowflake-o";
        } else if (nowMin <= 20) {
            category = "cool"; risk = "warning"; status = "偏涼"; icon = "fa-cloud";
        } else if (nowMax >= 28) {
            category = "hot"; status = "炎熱"; icon = "fa-fire";
        }

        // --- 6. 隨機演算法 (讓每個城市都不一樣) ---
        // 使用 (城市字碼總和 + 日期) 當作亂數種子
        let cityCode = item.city.split("").reduce((a,b)=>a+b.charCodeAt(0), 0);
        let uniqueSeed = cityCode + daySeed;

        // 從對應類別中挑選食物
        let foodList = foodDB[category];
        let foodPick = foodList[uniqueSeed % foodList.length];

        // 農民曆挑選
        let yiPick = yiDB[uniqueSeed % yiDB.length];
        let jiPick = jiDB[(uniqueSeed + 5) % jiDB.length];

        outputArray.push({
            city: item.city,
            min: nowMin,
            max: nowMax,
            risk: risk,
            status: status,
            icon: icon,
            food: foodPick,
            // 搜尋連結
            link: `https://www.google.com/search?q=${foodPick}+功效+食譜`,
            almanac: `宜：${yiPick} ｜ 忌：${jiPick}`,
            // 預警欄位
            nextTime: nextTime,
            forecastMsg: forecastMsg,
            alertClass: alertClass
        });
    });
}

msg.payload = outputArray;
return msg;
